module max_executables (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] arr_0,\n    input wire [7:0] arr_1,\n    input wire [7:0] arr_2,\n    input wire [7:0] arr_3,\n    input wire [7:0] arr_4,\n    input wire [7:0] arr_5,\n    input wire [7:0] arr_6,\n    input wire [7:0] arr_7,\n    input wire [3:0] N,\n    output reg [7:0] result,\n    output reg done\n);\n\nlocalparam [4:0] S_IDLE          = 5'd0;\nlocalparam [4:0] S_COMPUTE_PREFIX = 5'd1;\nlocalparam [4:0] S_SET_BEST0      = 5'd2;\nlocalparam [4:0] S_INIT_I         = 5'd3;\nlocalparam [4:0] S_LOOP_J_START   = 5'd4;\nlocalparam [4:0] S_COMPUTE_S      = 5'd5;\nlocalparam [4:0] S_COMPARE        = 5'd6;\nlocalparam [4:0] S_UPDATE         = 5'd7;\nlocalparam [4:0] S_NEXT_J         = 5'd8;\nlocalparam [4:0] S_NEXT_I         = 5'd9;\nlocalparam [4:0] S_DONE           = 5'd10;\n\nreg [4:0] state, next_state;\n\n// Arrays declaration\nreg [31:0] prefix [0:8];          // prefix[0] to prefix[8]\nreg [7:0]  best   [0:7];          // best[0] to best[7]\nreg [31:0] sums   [0:7];          // sums[0] to sums[7]\n\n// Temporary registers\nreg [3:0] prefix_idx;\nreg [3:0] i_idx;\nreg [3:0] j_idx;\nreg [31:0] temp_s;\nreg [7:0]  candidate;\nreg [7:0]  temp_best_reg;\nreg [31:0] temp_sum_reg;\n\ninteger i; // For initialization loops\n\n// Array access function\nfunction [7:0] get_arr;\n    input [3:0] idx;\n    begin\n        case (idx)\n            4'd0: get_arr = arr_0;\n            4'd1: get_arr = arr_1;\n            4'd2: get_arr = arr_2;\n            4'd3: get_arr = arr_3;\n            4'd4: get_arr = arr_4;\n            4'd5: get_arr = arr_5;\n            4'd6: get_arr = arr_6;\n            4'd7: get_arr = arr_7;\n            default: get_arr = 8'd0;\n        endcase\n    end\nendfunction\n\n// State register\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= S_IDLE;\n    end else begin\n        state <= next_state;\n    end\nend\n\n// Next state logic\nalways @(*) begin\n    next_state = state;\n    case (state)\n        S_IDLE: begin\n            if (start) next_state = S_COMPUTE_PREFIX;\n        end\n        \n        S_COMPUTE_PREFIX: begin\n            if (prefix_idx > N) next_state = S_SET_BEST0;\n        end\n        \n        S_SET_BEST0: begin\n            next_state = S_INIT_I;\n        end\n        \n        S_INIT_I: begin\n            next_state = S_LOOP_J_START;\n        end\n        \n        S_LOOP_J_START: begin\n            next_state = S_COMPUTE_S;\n        end\n        \n        S_COMPUTE_S: begin\n            next_state = S_COMPARE;\n        end\n        \n        S_COMPARE: begin\n            next_state = S_UPDATE;\n        end\n        \n        S_UPDATE: begin\n            next_state = S_NEXT_J;\n        end\n        \n        S_NEXT_J: begin\n            if (j_idx < i_idx) next_state = S_LOOP_J_START;\n            else next_state = S_NEXT_I;\n        end\n        \n        S_NEXT_I: begin\n            if (i_idx < (N - 4'd1)) next_state = S_INIT_I;\n            else next_state = S_DONE;\n        end\n        \n        S_DONE: begin\n            if (!start) next_state = S_IDLE;\n        end\n        \n        default: next_state = S_IDLE;\n    endcase\nend\n\n// Datapath and control logic\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        // Reset all registers\n        done <= 1'b0;\n        result <= 8'd0;\n        prefix_idx <= 4'd0;\n        i_idx <= 4'd0;\n        j_idx <= 4'd0;\n        temp_s <= 32'd0;\n        candidate <= 8'd0;\n        temp_best_reg <= 8'd0;\n        temp_sum_reg <= 32'd0;\n        \n        // Initialize arrays\n        for (i = 0; i < 9; i = i + 1) begin\n            prefix[i] <= 32'd0;\n        end\n        for (i = 0; i < 8; i = i + 1) begin\n            best[i] <= 8'd0;\n            sums[i] <= 32'd0;\n        end\n    end else begin\n        case (state)\n            S_IDLE: begin\n                done <= 1'b0;\n                result <= 8'd0;\n                if (start) begin\n                    prefix_idx <= 4'd1;\n                    prefix[0] <= 32'd0;\n                end\n            end\n            \n            S_COMPUTE_PREFIX: begin\n                if (prefix_idx <= N) begin\n                    prefix[prefix_idx] <= prefix[prefix_idx-1] + get_arr(prefix_idx-1);\n                    prefix_idx <= prefix_idx + 4'd1;\n                end\n            end\n            \n            S_SET_BEST0: begin\n                best[0] <= 8'd1;\n                sums[0] <= prefix[1];\n                i_idx <= 4'd1;\n            end\n            \n            S_INIT_I: begin\n                temp_best_reg <= 8'd1;\n                temp_sum_reg <= prefix[i_idx + 1];\n                j_idx <= 4'd0;\n            end\n            \n            S_LOOP_J_START: begin\n                // Prepare for j loop\n            end\n            \n            S_COMPUTE_S: begin\n                temp_s <= prefix[i_idx + 1] - prefix[j_idx + 1];\n            end\n            \n            S_COMPARE: begin\n                if (temp_s >= sums[j_idx]) begin\n                    candidate <= best[j_idx] + 8'd1;\n                end\n            end\n            \n            S_UPDATE: begin\n                if (candidate > temp_best_reg) begin\n                    temp_best_reg <= candidate;\n                    temp_sum_reg <= temp_s;\n                end else if (candidate == temp_best_reg && temp_s < temp_sum_reg) begin\n                    temp_sum_reg <= temp_s;\n                end\n            end\n            \n            S_NEXT_J: begin\n                j_idx <= j_idx + 4'd1;\n            end\n            \n            S_NEXT_I: begin\n                best[i_idx] <= temp_best_reg;\n                sums[i_idx] <= temp_sum_reg;\n                i_idx <= i_idx + 4'd1;\n            end\n            \n            S_DONE: begin\n                result <= best[N - 4'd1];\n                done <= 1'b1;\n            end\n            \n            default: begin\n                // Do nothing\n            end\n        endcase\n    end\nend\n\nendmodule